import{_ as o,o as a,c as s,ag as t}from"./chunks/framework.8tqBsFWt.js";const g=JSON.parse('{"title":"Phase 1.1 runbook — provision Supabase + wire Railway","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/postgres-phase-1-1-runbook.md","filePath":"decisions/postgres-phase-1-1-runbook.md"}'),r={name:"decisions/postgres-phase-1-1-runbook.md"};function i(n,e,l,c,d,p){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="phase-1-1-runbook-—-provision-supabase-wire-railway" tabindex="-1">Phase 1.1 runbook — provision Supabase + wire Railway <a class="header-anchor" href="#phase-1-1-runbook-—-provision-supabase-wire-railway" aria-label="Permalink to &quot;Phase 1.1 runbook — provision Supabase + wire Railway&quot;">​</a></h1><p><strong>Issue:</strong> <a href="https://github.com/talktalkmake/VERA/issues/438" target="_blank" rel="noreferrer">#438</a> · <strong>Phase:</strong> 1.1 (½ day) · <strong>Completed:</strong> 2026-04-21</p><p>Status: <strong>complete for prod.</strong> Staging deferred to Phase 2.1 (no value in carrying an unused free-tier project through Phase 1 which is local-only). This file records how we did it and the gotchas to remember when staging gets provisioned later.</p><h2 id="what-landed" tabindex="-1">What landed <a class="header-anchor" href="#what-landed" aria-label="Permalink to &quot;What landed&quot;">​</a></h2><ul><li>Supabase project <code>gdqmtevlnumwixevcmgg</code>, Pro plan, region <code>us-east-1</code> (matches Railway app region)</li><li>Daily backups: automatic on Pro, verified in Database → Backups</li><li>PITR: <strong>skipped.</strong> Add-on is $100–400/mo plus a forced Small-compute upgrade (~$15/mo). Daily backups cover VERA&#39;s recovery needs at this scale; PITR revisited if/when a real recovery scenario proves the cost.</li><li>Railway env var <code>DATABASE_URL_PROD</code> set to the Session Pooler connection string</li><li><code>psql</code> smoke test returns <code>PostgreSQL 17.6 on aarch64-unknown-linux-gnu</code></li></ul><h2 id="gotchas-read-before-provisioning-staging" tabindex="-1">Gotchas (read before provisioning staging) <a class="header-anchor" href="#gotchas-read-before-provisioning-staging" aria-label="Permalink to &quot;Gotchas (read before provisioning staging)&quot;">​</a></h2><p><strong>Use the Session Pooler connection string, never Direct.</strong> Supabase&#39;s Direct connection (<code>db.&lt;ref&gt;.supabase.co:5432</code>) is IPv6-only. Consumer ISPs, most Windows boxes, and Railway&#39;s outbound network are IPv4. Symptom: <code>Network is unreachable</code> from psql. Fix: Settings → Database → Connection string → <strong>Session pooler</strong> tab. Host becomes <code>aws-N-&lt;region&gt;.pooler.supabase.com</code>.</p><p><strong>Username on Session Pooler requires the project-ref suffix.</strong> Format is <code>postgres.&lt;project-ref&gt;</code>, not <code>postgres</code>. Supavisor uses the suffix to route to the right DB; without it, auth falls back to a generic <code>postgres</code> user and fails. Symptom: <code>password authentication failed for user &quot;postgres&quot;</code> (note the missing suffix in the error — that&#39;s the diagnostic).</p><p><strong>Make the database password URL-safe before anyone else sees the connection string.</strong> Supabase&#39;s generator uses <code>%</code>, <code>#</code>, <code>!</code>, <code>@</code>, etc. These collide with URL percent-encoding (<code>%</code>) and fragment parsing (<code>#</code>) when the password appears in a <code>postgresql://</code> URL, and with bash history expansion (<code>!</code>) on the command line. When resetting the password, <strong>type your own</strong>: 24+ chars of <code>a-zA-Z0-9</code> plus <code>-_</code> only.</p><p><strong>Don&#39;t skip region-matching.</strong> Supabase project region must match Railway&#39;s app region. Cross-region adds ~80ms per DAL call and compounds hard at morning-briefing time when 15+ sheet reads happen in sequence. VERA is <code>us-east-1</code> on both sides.</p><p><strong>Backups on Pro are automatic and non-optional.</strong> Database → Backups shows daily physical backups starting from provision time. No switch to flip.</p><h2 id="local-smoke-test-recipe-for-staging-later" tabindex="-1">Local smoke-test recipe (for staging later) <a class="header-anchor" href="#local-smoke-test-recipe-for-staging-later" aria-label="Permalink to &quot;Local smoke-test recipe (for staging later)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">psql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;postgresql://postgres.&lt;project-ref&gt;:&lt;password&gt;@aws-N-&lt;region&gt;.pooler.supabase.com:5432/postgres&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;select version();&quot;</span></span></code></pre></div><p>Single quotes around the URL prevent bash from touching any special chars in the password. Works from any IPv4-only machine including Railway.</p><h2 id="railway-wiring" tabindex="-1">Railway wiring <a class="header-anchor" href="#railway-wiring" aria-label="Permalink to &quot;Railway wiring&quot;">​</a></h2><ul><li>Variables → New Variable</li><li><code>DATABASE_URL_PROD</code> = the full Session Pooler URL with the real password</li><li>Don&#39;t set <code>USE_POSTGRES</code> — Phase 2 flips that per-tenant during cutover</li><li>Railway redeploys after the variable is saved. No code reads it yet, so the redeploy is a no-op.</li></ul><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>None needed — no app code references these env vars yet. Safe to leave.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><strong>Phase 1.2</strong> — add <code>pg</code>, <code>pg-pool</code>, <code>node-pg-migrate</code> to <code>package.json</code>. Local dev only; no Supabase connection needed until Phase 1.3 runs the first migration.</p>`,20)])])}const u=o(r,[["render",i]]);export{g as __pageData,u as default};
